package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;
/** Small, resumable on-device updates of Banana's own conversational weights. */
final class ReadingTraining{
 static final Object LOCK=new Object();
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-reading-training",0);}
 static JSONObject empty()throws Exception{return new JSONObject().put("version",1).put("enabled",true).put("tokenizer","").put("jobs",new JSONArray()).put("done",new JSONArray());}
 static void validate(JSONObject state)throws Exception{RuntimeProgram.keys(state,"version","enabled","tokenizer","jobs","done");if(state.getInt("version")!=1||!state.getString("tokenizer").matches("(?:[a-f0-9]{64})?"))throw new IOException("Formato de progreso desconocido");state.getBoolean("enabled");JSONArray jobs=state.getJSONArray("jobs"),done=state.getJSONArray("done");if(jobs.length()>1024||done.length()>1024||state.toString().length()>524288)throw new IOException("Progreso demasiado grande");Set<String> ids=new HashSet<>();for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);RuntimeProgram.keys(j,"id","sha256","ordinal","tokenOffset");if(!j.getString("id").matches("[a-f0-9]{64}")||!ids.add(j.getString("id"))||!j.getString("sha256").matches("[a-f0-9]{64}")||j.getInt("ordinal")<0||j.getInt("ordinal")>1000000||j.getInt("tokenOffset")<0||j.getInt("tokenOffset")>16384)throw new IOException("Cursor de aprendizaje inválido");}for(int i=0;i<done.length();i++)if(!done.getString(i).matches("[a-f0-9]{64}:[a-f0-9]{64}"))throw new IOException("Revisión aprendida inválida");}
 static JSONObject job(NotebookDisk.Doc doc)throws Exception{return new JSONObject().put("id",doc.id).put("sha256",doc.sha).put("ordinal",0).put("tokenOffset",0);}
 static boolean contains(JSONArray rows,String value)throws Exception{for(int i=0;i<rows.length();i++)if(rows.getString(i).equals(value))return true;return false;}
 static JSONObject state(Context c)throws Exception{JSONObject s=prefs(c).contains("state")?new JSONObject(prefs(c).getString("state","")):empty();validate(s);String raw=prefs(c).getString("pending","");if(!raw.isEmpty()){JSONObject p=new JSONObject(raw);String active=ModelDepot.row(c,"chat").optString("sha256");if(active.isEmpty()&&!(c instanceof NotebookDisk.Provider)){JSONObject embedded=ModelDepot.embedded(c).getJSONObject("models").optJSONObject("chat");if(embedded!=null)active=embedded.optString("sha256");}if(active.equals(p.getString("modelSha")))advance(s,p.getJSONObject("job"),p.getBoolean("done"));if(!prefs(c).edit().putString("state",s.toString()).remove("pending").commit())throw new IOException("Falta recuperar el progreso de una tanda");}return s;}
 static void save(Context c,JSONObject s)throws Exception{validate(s);if(!prefs(c).edit().putString("state",s.toString()).commit())throw new IOException("No pude guardar el progreso de lectura");}
 static void advance(JSONObject s,JSONObject job,boolean finished)throws Exception{JSONArray next=new JSONArray(),old=s.getJSONArray("jobs");for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("id").equals(job.getString("id")))next.put(old.getJSONObject(i));if(!finished)next.put(job);else{JSONArray done=s.getJSONArray("done"),updated=new JSONArray();String key=job.getString("id")+":"+job.getString("sha256");for(int i=Math.max(0,done.length()-1023);i<done.length();i++)if(!done.getString(i).equals(key))updated.put(done.getString(i));updated.put(key);s.put("done",updated);}s.put("jobs",next);}
 static void enqueue(Context c,NotebookDisk.Doc doc)throws Exception{synchronized(LOCK){JSONObject s=state(c);String key=doc.id+":"+doc.sha;if(contains(s.getJSONArray("done"),key))return;JSONArray next=new JSONArray();JSONObject current=null;JSONArray jobs=s.getJSONArray("jobs");Set<String> live=new HashSet<>();for(NotebookDisk.Doc d:NotebookDisk.of(c).index.list(1024))live.add(d.id);for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if(j.getString("id").equals(doc.id)){if(j.getString("sha256").equals(doc.sha))current=j;}else if(live.contains(j.getString("id")))next.put(j);}JSONArray ordered=new JSONArray().put(current==null?job(doc):current);for(int i=0;i<next.length();i++)ordered.put(next.getJSONObject(i));s.put("jobs",ordered);save(c,s);}}
 static String afterLearning(Context c)throws Exception{synchronized(LOCK){NotebookDisk disk=NotebookDisk.of(c);NotebookDisk.Doc doc=disk.index.get(disk.index.meta("last"));if(doc==null)return "No encontré una fuente nueva para entrenar.";enqueue(c,doc);if(!state(c).getBoolean("enabled"))return "El documento quedó en la cola; el entrenamiento automático está pausado.";}if(c instanceof NotebookDisk.Provider)return "Fuente encolada; este contexto de prueba no dispone del entrenador Android.";LearningLoop.wake(c);return "Documento encolado para entrenamiento y ejercicios en segundo plano. Podés seguir conversando; consultá el estado del aprendizaje continuo para ver el resultado.";}
 static JSONObject portable(Context c)throws Exception{synchronized(LOCK){return new JSONObject(state(c).toString());}}
 static void restore(Context c,JSONObject data)throws Exception{synchronized(LOCK){validate(data);if(!prefs(c).contains("state"))save(c,data);}}
 static void forgot(Context c)throws Exception{synchronized(LOCK){JSONObject s=state(c);s.put("jobs",new JSONArray()).put("done",new JSONArray());if(!prefs(c).edit().putString("state",s.toString()).remove("pending").remove("report").commit())throw new IOException("Biblioteca borrada; falta limpiar sus cursores de entrenamiento");}}
 static void collect(Context c)throws Exception{synchronized(LOCK){JSONObject s=state(c);List<NotebookDisk.Doc> docs=NotebookDisk.of(c).index.list(1024);Map<String,NotebookDisk.Doc> live=new LinkedHashMap<>();for(NotebookDisk.Doc d:docs)live.put(d.id,d);Set<String> done=new HashSet<>();JSONArray completed=s.getJSONArray("done");for(int i=0;i<completed.length();i++)done.add(completed.getString(i));Set<String> queued=new HashSet<>();JSONArray old=s.getJSONArray("jobs"),next=new JSONArray();for(int i=0;i<old.length();i++){JSONObject j=old.getJSONObject(i);NotebookDisk.Doc d=live.get(j.getString("id"));if(d!=null&&d.sha.equals(j.getString("sha256"))&&!done.contains(d.id+":"+d.sha)){next.put(j);queued.add(d.id);}}for(NotebookDisk.Doc d:docs)if(!queued.contains(d.id)&&!done.contains(d.id+":"+d.sha))next.put(job(d));if(!next.toString().equals(old.toString())){s.put("jobs",next);save(c,s);}}}
 static BananaTransformer original(Context c)throws Exception{return new BananaTransformer(c.getAssets().open(ModelDepot.CHAT),c.getAssets().open("chat34/vocab.txt"),c.getAssets().open("chat34/tokenizer.json"));}
 static final java.util.concurrent.locks.ReentrantLock TRAIN=new java.util.concurrent.locks.ReentrantLock();
 static String run(Context c,int batches,boolean authoredIfEmpty)throws Exception{return run(c,batches,authoredIfEmpty,false);}
 static String background(Context c)throws Exception{return run(c,1,false,true);}
 static boolean same(JSONObject a,JSONObject b){return a!=null&&b!=null&&a.optString("id").equals(b.optString("id"))&&a.optString("sha256").equals(b.optString("sha256"))&&a.optInt("ordinal")==b.optInt("ordinal")&&a.optInt("tokenOffset")==b.optInt("tokenOffset");}
 static void current(Context c,JSONObject expected)throws Exception{if(expected==null)return;JSONObject s=state(c);JSONArray jobs=s.getJSONArray("jobs");for(int i=0;i<jobs.length();i++)if(same(jobs.getJSONObject(i),expected))return;throw new IOException("La fuente o el cursor cambió durante la tanda; no activé ese candidato");}
 static void progress(Context c,JSONObject expected,JSONObject next,boolean finished)throws Exception{synchronized(LOCK){current(c,expected);JSONObject fresh=state(c);advance(fresh,next,finished);save(c,fresh);}}
 static String run(Context c,int batches,boolean authoredIfEmpty,boolean background)throws Exception{if(c instanceof NotebookDisk.Provider)return "El motor Android se prueba por separado; el conocimiento quedó guardado.";if(!TRAIN.tryLock())return "Ya hay una tanda de pesos en curso; conservé tu pedido y los documentos.";Thread previous=JavaChat.owner;String previousProgress=JavaChat.progress;if(!background)JavaChat.owner=Thread.currentThread();StringBuilder receipt=new StringBuilder();ReadingBudget governor=new ReadingBudget(c,background||batches>1?360:180,background);try{for(int n=0;n<batches;n++){governor.check();JSONObject current=null;NotebookDisk.Doc doc=null;NotebookDisk.Hit hit=null;
  synchronized(LOCK){JSONObject s=state(c);String tokenizer=JavaMethodEditor.hash(AppJavaChat.asset(c,"chat34/tokenizer.json",1000000));if(!s.getString("tokenizer").isEmpty()&&!s.getString("tokenizer").equals(tokenizer)){JSONArray reset=s.getJSONArray("jobs");for(int i=0;i<reset.length();i++)reset.getJSONObject(i).put("ordinal",0).put("tokenOffset",0);s.put("done",new JSONArray());}s.put("tokenizer",tokenizer);save(c,s);JSONArray jobs=s.getJSONArray("jobs");
   while(jobs.length()>0){current=jobs.getJSONObject(0);doc=NotebookDisk.of(c).index.get(current.getString("id"));if(doc==null||!doc.sha.equals(current.getString("sha256"))){advance(s,current,true);save(c,s);jobs=s.getJSONArray("jobs");current=null;continue;}List<NotebookDisk.Hit> rows=NotebookDisk.of(c).index.slice(doc.id,current.getInt("ordinal"),1);if(rows.isEmpty()){advance(s,current,true);save(c,s);jobs=s.getJSONArray("jobs");current=null;continue;}hit=rows.get(0);break;}}
  if(hit==null&&!authoredIfEmpty){receipt.append("No quedan bloques pendientes en esta cola.\n");break;}String revision=ModelDepot.revision(c,"chat");BananaTransformer m=NeuralTraining.chat(c);ReadingWeights.Batch batch=hit==null?ReadingWeights.authored(m):background?SourceExercises.batch(m,doc,hit.text,hit.ordinal,current.getInt("tokenOffset"),LearningLoop.prefs(c).getInt("round",1)):ReadingWeights.source(m,doc,hit.text,hit.ordinal,current.getInt("tokenOffset"));JSONObject next=current==null?null:new JSONObject(current.toString());boolean finished=false;if(next!=null){next.put("ordinal",batch.nextOrdinal).put("tokenOffset",batch.nextOffset);finished=batch.nextOffset==0&&NotebookDisk.of(c).index.slice(doc.id,batch.nextOrdinal,1).isEmpty();}
  if(batch.train.isEmpty()){progress(c,current,next,finished);receipt.append("Bloque sin ejemplos suficientes: conservé el texto y avancé el cursor sin cambiar pesos.\n");continue;}
  if(!background)JavaChat.phase("Pesos conversacionales: entrenando una tanda pequeña de lectura y diálogo…");JSONObject attempt=batch.exercise==null?null:SourceExercises.attempt(m,batch.exercise,governor);JSONObject report=ReadingWeights.fit(m,original(c),batch,governor,background);report.put("sourceTruthVerified",false);if(attempt!=null)report.put("exercise",attempt);governor.check();
  synchronized(LOCK){current(c,current);if(doc!=null){NotebookDisk.Doc latest=NotebookDisk.of(c).index.get(doc.id);if(latest==null||!latest.sha.equals(doc.sha))throw new IOException("La fuente cambió durante la tanda; no activé ese candidato");}}
  if(report.getBoolean("accepted")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();m.save(bytes);File checkpoint=ModelDepot.save(c,"chat-reading",bytes.toByteArray());boolean published=false;try{try(InputStream in=new FileInputStream(checkpoint)){BananaTransformer reopened=new BananaTransformer(in,c.getAssets().open("chat34/vocab.txt"),c.getAssets().open("chat34/tokenizer.json"));if(Math.abs(ReadingWeights.evaluate(reopened,batch.eval,governor)-report.getDouble("after"))>1e-6)throw new IOException("El checkpoint no reproduce la evaluación de lectura");}report.put("checkpointSha256",ProjectRuntime.digest(checkpoint));governor.check();synchronized(LOCK){if(background)governor.check();current(c,current);if(doc!=null){NotebookDisk.Doc latest=NotebookDisk.of(c).index.get(doc.id);if(latest==null||!latest.sha.equals(doc.sha))throw new IOException("La fuente cambió antes de publicar");}if(next!=null&&!prefs(c).edit().putString("pending",new JSONObject().put("job",next).put("done",finished).put("modelSha",report.getString("checkpointSha256")).toString()).commit())throw new IOException("No pude preparar el progreso antes de activar pesos");ModelDepot.publish(c,"chat",checkpoint,report,revision);published=true;if(next!=null){JSONObject fresh=state(c);if(prefs(c).contains("pending")){advance(fresh,next,finished);if(!prefs(c).edit().putString("state",fresh.toString()).remove("pending").commit())throw new IOException("Pesos activados; recuperaré el cursor al continuar");}}}prune(c);}finally{if(!published)checkpoint.delete();}receipt.append("Entrené y activé pesos conversacionales nuevos con una parte de esta lectura.\n");
  }else{if(next!=null)progress(c,current,next,finished);receipt.append("Entrené un candidato, pero conservé los pesos activos porque no pasó los controles.\n");}
  if(!prefs(c).edit().putString("report",report.toString()).remove("pause").commit())throw new IOException("Modelo evaluado; falta guardar su informe");if(background)LearningLoop.result(c,report);receipt.append("Pérdida de validación: ").append(String.format(java.util.Locale.ROOT,"%.5f → %.5f",report.getDouble("before"),report.getDouble("after"))).append(".\n");if(hit==null)break;
 }return receipt.append("Son tandas pequeñas y evaluaciones locales; no garantizan comprensión general ni recordar toda la fuente en los pesos. El documento completo sigue disponible.").toString();
 }catch(ReadingBudget.Paused pause){prefs(c).edit().putString("pause",pause.getMessage()).commit();if(background)throw pause;return receipt+"Entrenamiento pendiente por "+pause.getMessage()+". Conservé los documentos y el último checkpoint válido.";}finally{if(!background){JavaChat.owner=previous;JavaChat.progress=previousProgress;}TRAIN.unlock();}}
 static void prune(Context c)throws Exception{Set<String> keep=new HashSet<>();JSONObject active=ModelDepot.row(c,"chat");if(active.has("path"))keep.add(new File(active.getString("path")).getCanonicalPath());String backup=ModelDepot.prefs(c).getString("chatBackup","");if(!backup.isEmpty())keep.add(new File(new JSONObject(backup).getString("path")).getCanonicalPath());File[] files=c.getDir("model-training",0).listFiles();if(files!=null)for(File f:files)if(f.getName().startsWith("chat-reading-")&&!keep.contains(f.getCanonicalPath()))f.delete();}
 static String action(String input){String q=NaturalCoding.normalize(input);if(q.matches("pausa el entrenamiento de lecturas|pausa el aprendizaje de pesos|no entrenes con paginas|no entrenes con lo que leo"))return "pause";if(q.matches("activa el entrenamiento de lecturas|aprende pesos de lo que leo|activa el aprendizaje de pesos"))return "enable";if(q.matches("estado del entrenamiento de lecturas|estado entrenamiento de lecturas|estado pesos conversacionales|que aprendiste en tus pesos|como va el aprendizaje de las lecturas"))return "status";if(q.matches("deshace el aprendizaje de las lecturas|recupera los pesos anteriores de las lecturas"))return "undo";if(q.matches("entrena mas tiempo con mis lecturas|continua entrenando con mis lecturas|continua aprendiendo de tus lecturas"))return "long";if(q.matches("mejora (?:tus|mis|los) pesos conversacionales|mejora los pesos del chat con mis lecturas|entrena con mis lecturas|aprende de lo que leiste|aprende de tus lecturas"))return "train";return "";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String action=action(input);if(action.isEmpty())return null;try{String text;if(action.equals("pause")){LearningLoop.pause(c);text="Pausé el entrenamiento automático de lecturas. Seguiré guardando y consultando documentos.";}else if(action.equals("enable")){LearningLoop.enable(c);text="Activé las tandas automáticas de lectura y ejercicios en segundo plano.";}else if(action.equals("status")){JSONObject s; synchronized(LOCK){s=state(c);}text="Pesos conversacionales desde lecturas\nAutomático: "+s.getBoolean("enabled")+" · fuentes pendientes: "+s.getJSONArray("jobs").length()+" · revisiones recorridas: "+s.getJSONArray("done").length()+".\nÚltima pausa: "+prefs(c).getString("pause","ninguna")+"\nÚltima evaluación: "+prefs(c).getString("report","sin tanda")+"\n"+LearningLoop.summary(c);}else if(action.equals("undo")){LearningLoop.pause(c);text=ModelDepot.undo(c,"chat")+"\nPausé el entrenamiento automático. Los documentos se conservan.";}else{synchronized(LOCK){collect(c);}text=run(c,action.equals("long")?3:1,true);}return MobileCore.say(c,text,"aprendizaje_pesos");}catch(Exception e){return MobileCore.say(c,"Conservé el conocimiento. No completé una tanda nueva de pesos: "+AndroidRepair.summary(e),"aprendizaje_pesos");}}
}
